-- 3. Articles
INSERT INTO `articles` (`id`, `slug`, `title`, `excerpt`, `body_html`, `cover_url`, `cover_alt`, `category_slug`, `category_name`, `author_name`, `status`, `published_at`, `seo_title`, `seo_description`) VALUES ('article-1', 'strategi-mitigasi-risiko-litigasi-perjanjian-bisnis', 'Strategi Mitigasi Risiko Litigasi dalam Perjanjian Bisnis Komersial', 'Penyusunan klausul penyelesaian sengketa, pembatasan tanggung jawab, dan klausul keadaan kahar guna mengantisipasi wanprestasi mitra usaha.', '<p>Dalam dinamika bisnis komersial, sengketa antar mitra sering kali berakar dari perumusan klausul kontrak yang multitafsir. Penyusunan perjanjian yang cermat harus memperhitungkan mekanisme pencegahan dan penyelesaian sengketa sejak tahap negosiasi.</p><h2>1. Klausul Pilihan Forum dan Penyelesaian Sengketa</h2><p>Menentukan forum penyelesaian sengketa secara tegas—baik melalui Pengadilan Negeri maupun forum alternatif seperti mediasi dan arbitrase—sangat penting untuk menjaga kepastian hukum bagi para pihak.</p><h2>2. Pembatasan Tanggung Jawab dan Keadaan Kahar (Force Majeure)</h2><p>Perumusan definisi keadaan kahar serta batasan tanggung jawab perlu merujuk pada ketentuan Kitab Undang-Undang Hukum Perdata dan regulasi sektoral yang berlaku di Indonesia.</p>', '/images/practice-corporate.webp', 'Ilustrasi ruang diskusi hukum korporasi dan kontrak komersial', 'hukum-korporasi', 'Hukum Korporasi & Bisnis', 'Tim Redaksi FS dan Rekan', 'published', '2026-10-12 09:00:00', 'Mitigasi Risiko Litigasi Kontrak Bisnis | FS dan Rekan', 'Panduan mitigasi risiko sengketa dalam penyusunan kontrak komersial oleh Ferdinan Silalahi dan Rekan Law Firm.') ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `status` = VALUES(`status`);
INSERT INTO `articles` (`id`, `slug`, `title`, `excerpt`, `body_html`, `cover_url`, `cover_alt`, `category_slug`, `category_name`, `author_name`, `status`, `published_at`, `seo_title`, `seo_description`) VALUES ('article-2', 'penyelesaian-sengketa-kepemilikan-lahan-dan-uji-tuntas', 'Penyelesaian Sengketa Kepemilikan Lahan & Uji Tuntas (Legal Due Diligence)', 'Pentingnya pemeriksaan riwayat alas hak dan verifikasi dokumen pertanahan sebelum melakukan transaksi aset properti.', '<p>Sengketa pertanahan kerap melibatkan tumpang tindih dokumen kepemilikan atau ketidakjelasan riwayat penguasaan fisik. Uji tuntas hukum (<em>legal due diligence</em>) merupakan langkah preventif utama sebelum transaksi properti dilakukan.</p><h2>1. Verifikasi Administrasi Pertanahan</h2><p>Pemeriksaan kesesuaian data fisik dan data yuridis pada dokumen pertanahan bertujuan memastikan tidak adanya catatan blokir, sita jaminan, atau sengketa yang sedang berjalan.</p><h2>2. Pemeriksaan Riwayat Penguasaan Fisik</h2><p>Selain pemeriksaan dokumen, peninjauan batas sempadan dan riwayat penguasaan fisik di lapangan membantu memitigasi klaim pihak ketiga di kemudian hari.</p>', '/images/article-land.webp', 'Ilustrasi dokumen hukum pertanahan dan agraria', 'agraria-dan-properti', 'Agraria & Properti', 'Tim Redaksi FS dan Rekan', 'published', '2026-10-08 09:00:00', 'Uji Tuntas & Sengketa Pertanahan | FS dan Rekan', 'Langkah uji tuntas hukum (legal due diligence) untuk mencegah sengketa pertanahan dan properti.') ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `status` = VALUES(`status`);
INSERT INTO `articles` (`id`, `slug`, `title`, `excerpt`, `body_html`, `cover_url`, `cover_alt`, `category_slug`, `category_name`, `author_name`, `status`, `published_at`, `seo_title`, `seo_description`) VALUES ('article-3', 'perjanjian-perkawinan-dan-perlindungan-harta-keluarga', 'Pentingnya Perjanjian Perkawinan & Penataan Harta Keluarga', 'Instrumen hukum perdata untuk mengatur pemisahan harta bawaan dan tanggung jawab perikatan dalam keluarga.', '<p>Perjanjian perkawinan (baik sebelum maupun selama ikatan perkawinan berlangsung sesuai ketentuan peraturan perundang-undangan) merupakan instrumen hukum untuk memberikan kejelasan mengenai status harta dan tanggung jawab perdata masing-masing pasangan.</p><h2>1. Pemisahan Tanggung Jawab Perikatan Usaha</h2><p>Dengan adanya akta notariil yang dicatatkan pada instansi berwenang, tata kelola harta pribadi dan harta bersama menjadi lebih tertib apabila salah satu pihak menjalankan kegiatan usaha dengan risiko komersial.</p><h2>2. Kepastian Perencanaan Harta Keluarga</h2><p>Penataan dokumen kepemilikan aset sejak dini turut membantu meminimalkan potensi perselisihan waris di masa mendatang.</p>', '/images/article-family.webp', 'Ilustrasi konsultasi hukum keluarga dan perdata', 'perdata-keluarga', 'Perdata Keluarga', 'Tim Redaksi FS dan Rekan', 'published', '2026-09-28 09:00:00', 'Perjanjian Perkawinan & Harta Keluarga | FS dan Rekan', 'Kajian hukum perdata mengenai perjanjian perkawinan dan tata kelola harta keluarga.') ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `status` = VALUES(`status`);
INSERT INTO `articles` (`id`, `slug`, `title`, `excerpt`, `body_html`, `cover_url`, `cover_alt`, `category_slug`, `category_name`, `author_name`, `status`, `published_at`, `seo_title`, `seo_description`) VALUES ('article-draft-1', 'draf-internal-belum-terbit', '[Draf Internal] Analisis Restrukturisasi Kredit Korporasi', 'Artikel ini masih berstatus draf dan hanya tampil di panel admin atau mode pratinjau admin.', '<p>Draf kajian hukum internal yang belum dipublikasikan ke pengunjung umum.</p>', '/images/practice-banking.webp', 'Ilustrasi restrukturisasi perbankan', 'hukum-korporasi', 'Hukum Korporasi & Bisnis', 'Tim Redaksi FS dan Rekan', 'draft', '2026-10-24 09:00:00', 'Analisis Restrukturisasi Kredit | FS dan Rekan', 'Draf internal kajian restrukturisasi kredit.') ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `status` = VALUES(`status`);

-- 4. Practice Areas (10 Bidang Layanan Hukum)
INSERT INTO `practice_areas` (`id`, `slug`, `name`, `label`, `summary`, `description`, `advocacy_scope_json`, `icon`, `image`, `display_order`, `is_published`) VALUES ('practice-area-1', 'litigasi-korporasi-dan-komersial', 'Litigasi Korporasi & Komersial', 'BISNIS', 'Pendampingan penyelesaian sengketa korporasi, perjanjian komersial, tata kelola perusahaan, serta perlindungan kepentingan hukum pelaku usaha.', 'Penyelesaian Sengketa Kontrak & Tata Kelola Perusahaan', '["Penanganan sengketa pemegang saham, RUPS, dan organ perseroan","Penyusunan, peninjauan, dan negosiasi kontrak bisnis komersial","Representasi litigasi perdata dan komersial di pengadilan"]', '', '/images/practice-corporate.webp', 1, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`);
INSERT INTO `practice_areas` (`id`, `slug`, `name`, `label`, `summary`, `description`, `advocacy_scope_json`, `icon`, `image`, `display_order`, `is_published`) VALUES ('practice-area-2', 'sengketa-pertanahan-dan-agraria', 'Sengketa Pertanahan & Agraria', 'PROPERTI', 'Pendampingan sengketa hak atas tanah, pemeriksaan keabsahan dokumen pertanahan (legal due diligence), dan penyelesaian klaim penguasaan lahan.', 'Kepastian Alas Hak & Penanganan Sengketa Pertanahan', '["Uji tuntas hukum (legal due diligence) sebelum transaksi aset properti","Pendampingan sengketa tumpang tindih sertifikat dan riwayat kepemilikan","Mediasi dan litigasi sengketa hak atas tanah di peradilan"]', '', '/images/article-land.webp', 2, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`);
INSERT INTO `practice_areas` (`id`, `slug`, `name`, `label`, `summary`, `description`, `advocacy_scope_json`, `icon`, `image`, `display_order`, `is_published`) VALUES ('practice-area-3', 'hukum-perdata-dan-perlindungan-aset', 'Hukum Perdata & Perlindungan Aset', 'ASET', 'Penanganan gugatan wanprestasi, perbuatan melawan hukum (PMH), permohonan sita jaminan, serta perancangan instrumen perlindungan aset.', 'Penegakan Hak Perdata & Perlindungan Aset Klien', '["Penyusunan somasi, gugatan wanprestasi, dan perbuatan melawan hukum","Permohonan sita jaminan dan pelaksanaan putusan pengadilan","Pendampingan negosiasi pemulihan hak keperdataan"]', '', '/images/lady-justice.webp', 3, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`);
INSERT INTO `practice_areas` (`id`, `slug`, `name`, `label`, `summary`, `description`, `advocacy_scope_json`, `icon`, `image`, `display_order`, `is_published`) VALUES ('practice-area-4', 'hukum-pidana-umum-dan-tipikor', 'Hukum Pidana Umum & Tipikor', 'PIDANA', 'Pendampingan hukum pada tahap pelaporan, penyelidikan, penyidikan, hingga pembelaan di persidangan perkara pidana umum dan tindak pidana korupsi.', 'Pendampingan Proses Hukum & Pembelaan di Persidangan', '["Pendampingan saksi, pelapor, maupun tersangka dalam pemeriksaan","Penyusunan eksepsi, pledoi, memori banding, kasasi, dan PK","Penanganan perkara tindak pidana umum dan tindak pidana khusus/korupsi"]', '', '/images/hero-slide-courtroom.webp', 4, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`);
INSERT INTO `practice_areas` (`id`, `slug`, `name`, `label`, `summary`, `description`, `advocacy_scope_json`, `icon`, `image`, `display_order`, `is_published`) VALUES ('practice-area-5', 'hak-kekayaan-intelektual-hki', 'Hak Kekayaan Intelektual (HKI)', 'HKI', 'Perlindungan hukum atas merek, hak cipta, paten, desain industri, rahasia dagang, serta penyelesaian sengketa kekayaan intelektual.', 'Perlindungan Kekayaan Intelektual & Perjanjian Lisensi', '["Konsultasi pendaftaran dan pengelolaan portofolio HKI","Penyusunan perjanjian lisensi, waralaba, dan kerahasiaan (NDA)","Penanganan sengketa pelanggaran merek dan hak cipta di Pengadilan Niaga"]', '', '/images/practice-ip.webp', 5, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`);
INSERT INTO `practice_areas` (`id`, `slug`, `name`, `label`, `summary`, `description`, `advocacy_scope_json`, `icon`, `image`, `display_order`, `is_published`) VALUES ('practice-area-6', 'ketenagakerjaan-dan-phi', 'Ketenagakerjaan & PHI', 'INDUSTRIAL', 'Pendampingan hubungan industrial, perundingan bipartit dan tripartit, penyusunan kontrak kerja, serta penyelesaian sengketa di Pengadilan Hubungan Industrial.', 'Kepatuhan Ketenagakerjaan & Penyelesaian Perselisihan Hubungan Industrial', '["Penyusunan Perjanjian Kerja, Peraturan Perusahaan (PP), dan PKB","Pendampingan perundingan bipartit dan mediasi tripartit","Representasi sengketa Perselisihan Hubungan Industrial (PHI)"]', '', '/images/practice-labor.webp', 6, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`);
INSERT INTO `practice_areas` (`id`, `slug`, `name`, `label`, `summary`, `description`, `advocacy_scope_json`, `icon`, `image`, `display_order`, `is_published`) VALUES ('practice-area-7', 'kepailitan-dan-pkpu-niaga', 'Kepailitan & PKPU Niaga', 'RESTRUKTURISASI', 'Pendampingan perkara Penundaan Kewajiban Pembayaran Utang (PKPU) dan kepailitan bagi kreditur maupun debitur di Pengadilan Niaga.', 'Restrukturisasi Kewajiban Utang & Perkara Pengadilan Niaga', '["Penyusunan permohonan PKPU dan kepailitan di Pengadilan Niaga","Pendampingan rapat kreditur, verifikasi tagihan, dan proposal perdamaian","Pengelolaan dokumen restrukturisasi utang korporasi"]', '', '/images/practice-bankruptcy.webp', 7, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`);
INSERT INTO `practice_areas` (`id`, `slug`, `name`, `label`, `summary`, `description`, `advocacy_scope_json`, `icon`, `image`, `display_order`, `is_published`) VALUES ('practice-area-8', 'arbitrase-dan-mediasi-bisnis', 'Arbitrase & Mediasi Bisnis', 'ADR', 'Penyelesaian sengketa komersial di luar pengadilan melalui mekanisme negosiasi, mediasi, dan forum arbitrase secara efektif dan terjaga kerahasiaannya.', 'Penyelesaian Sengketa Alternatif (ADR) & Mediasi Komersial', '["Perumusan strategi negosiasi dan fasilitasi mediasi bisnis","Pendampingan proses beracara pada forum arbitrase","Pendaftaran dan pelaksanaan putusan perdamaian atau arbitrase"]', '', '/images/gavel-banner.webp', 8, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`);
INSERT INTO `practice_areas` (`id`, `slug`, `name`, `label`, `summary`, `description`, `advocacy_scope_json`, `icon`, `image`, `display_order`, `is_published`) VALUES ('practice-area-9', 'hukum-perbankan-dan-pembiayaan', 'Hukum Perbankan & Pembiayaan', 'FINANSIAL', 'Pendampingan hukum di bidang perbankan dan pembiayaan, termasuk penanganan kredit bermasalah (Non-Performing Loan/NPL), restrukturisasi, dan eksekusi agunan.', 'Kepatuhan Perbankan, Restrukturisasi Kredit & Penanganan NPL', '["Penanganan pemulihan kredit bermasalah (Non-Performing Loan / NPL)","Koordinasi restrukturisasi fasilitas kredit dan pengelolaan dokumen jaminan","Pendampingan proses eksekusi hak tanggungan dan jaminan fidusia"]', '', '/images/practice-banking.webp', 9, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`);
INSERT INTO `practice_areas` (`id`, `slug`, `name`, `label`, `summary`, `description`, `advocacy_scope_json`, `icon`, `image`, `display_order`, `is_published`) VALUES ('practice-area-10', 'hukum-keluarga-dan-waris', 'Hukum Keluarga & Waris', 'WARIS', 'Konsultasi dan pendampingan perkara hukum keluarga, penyusunan perjanjian perkawinan, penataan harta keluarga, serta penyelesaian sengketa waris.', 'Pendampingan Hukum Keluarga & Penyelesaian Waris', '["Penyusunan dan peninjauan perjanjian perkawinan","Konsultasi pembagian waris dan penataan harta keluarga","Pendampingan penyelesaian sengketa keperdataan keluarga di pengadilan"]', '', '/images/article-family.webp', 10, 1) ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`);

-- 5. Team Members (Profil Advokat & Konsultan Hukum)
INSERT INTO `team_members` (`id`, `slug`, `full_name`, `honorific`, `display_name`, `role_title`, `group_name`, `motto`, `short_bio`, `full_bio`, `education_json`, `credentials_json`, `languages_json`, `tags_json`, `photo_json`, `display_order`, `is_published`) VALUES ('team-1', 'ferdinan-hasiholan-silalahi', 'Ferdinan Hasiholan Silalahi', 'S.H.', 'Ferdinan Hasiholan Silalahi, S.H.', 'Pendiri dan Managing Partner', 'Pendiri dan Managing Partner', 'Life has to be meaningful', 'Pendiri dan Managing Partner. Berpegang pada motto "Life has to be meaningful", beliau mendirikan firma ini untuk menghadirkan pendampingan hukum yang terpercaya dan mudah diakses.', 'Ferdinan Hasiholan Silalahi, S.H. merupakan Pendiri sekaligus Managing Partner di Ferdinan Silalahi dan Rekan Law Firm. Lahir di Jakarta dan memiliki kebanggaan terhadap warisan budaya Batak, beliau menyelesaikan pendidikan Sarjana Hukum di Fakultas Hukum Universitas Tanjungpura.\n\nBerpegang pada motto hidup "Life has to be meaningful", Ferdinan meyakini bahwa profesi hukum bukan sekadar pekerjaan, melainkan sebuah panggilan untuk memberikan manfaat dan menciptakan dampak positif bagi masyarakat. Filosofi tersebut menjadi landasan dalam perjalanan kariernya sekaligus dasar berdirinya firma hukum ini.\n\nBerangkat dari kepeduliannya terhadap masih terbatasnya akses masyarakat Indonesia terhadap layanan hukum yang berkualitas, beliau mendirikan firma ini dengan visi untuk menghadirkan pendampingan hukum yang terpercaya, mudah diakses, dan profesional bagi individu, pelaku usaha, maupun masyarakat yang membutuhkan.\n\nDengan menjunjung tinggi nilai integritas, profesionalisme, dan keadilan, Ferdinan berkomitmen memberikan solusi hukum yang efektif dan berorientasi pada kebutuhan klien. Beliau juga meyakini bahwa setiap klien tidak hanya berhak memperoleh pendampingan hukum yang kompeten, tetapi juga dedikasi, kepedulian, dan penghormatan dalam setiap tahapan proses hukum.', '["S.H., Fakultas Hukum Universitas Tanjungpura"]', '[]', '[]', '[]', '{"id":"media-ferdinan-hasiholan-silalahi","filename":"ferdinan-hasiholan-silalahi.webp","sourceFilename":"Ferdinan.png","mimeType":"image/webp","size":68540,"width":800,"height":1000,"aspectRatio":"4:5","url":"/team/ferdinan-hasiholan-silalahi.webp","sizes":{"sm":"/team/ferdinan-hasiholan-silalahi-400w.webp","md":"/team/ferdinan-hasiholan-silalahi-600w.webp","lg":"/team/ferdinan-hasiholan-silalahi-800w.webp"},"srcSet":"/team/ferdinan-hasiholan-silalahi-400w.webp 400w, /team/ferdinan-hasiholan-silalahi-600w.webp 600w, /team/ferdinan-hasiholan-silalahi-800w.webp 800w","alt":"Foto Ferdinan Hasiholan Silalahi, S.H."}', 1, 1) ON DUPLICATE KEY UPDATE `display_name` = VALUES(`display_name`), `role_title` = VALUES(`role_title`);
INSERT INTO `team_members` (`id`, `slug`, `full_name`, `honorific`, `display_name`, `role_title`, `group_name`, `motto`, `short_bio`, `full_bio`, `education_json`, `credentials_json`, `languages_json`, `tags_json`, `photo_json`, `display_order`, `is_published`) VALUES ('team-2', 'basit-rezki', 'Basit Rezki', 'S.H.', 'Basit Rezki, S.H.', 'Associate', 'Associate', NULL, 'Associate dan advokat berlisensi terakreditasi Perhimpunan Advokat Indonesia, berfokus pada riset hukum, penyusunan dokumen perkara, dan pendampingan persidangan.', 'Basit Rezki, S.H. adalah Associate di Ferdinan Silalahi dan Rekan Law Firm yang merupakan advokat berlisensi dan telah terakreditasi oleh Perhimpunan Advokat Indonesia. Basit menempuh pendidikan hukum di Fakultas Hukum Universitas Dirgantara Marsekal Suryadarma dan memiliki dedikasi tinggi terhadap penegakan supremasi hukum, didukung kemampuan analisis hukum dan riset yang mumpuni.\n\nSebelum bergabung, Basit mengembangkan keahliannya melalui pengalaman magang di beberapa kantor hukum, tempat beliau terlibat dalam pendampingan klien pada proses pelaporan tindak pidana, penyusunan berbagai dokumen hukum seperti kontrak, gugatan, *pledoi*, hingga memori kasasi, serta aktif menghadiri dan mendokumentasikan jalannya persidangan. Pengalamannya turut mencakup pendampingan klien dalam kasus tindak pidana kekerasan terhadap anak, penelaahan kontrak, hingga peran sebagai negosiator dalam perjanjian penerbitan buku bagi kliennya. Dengan kemampuan komunikasi yang baik, kerja sama tim yang kuat, serta penguasaan bahasa Inggris dan Jepang (bersertifikat JFT A2), Basit siap memberikan layanan hukum yang profesional dan berkualitas bagi klien.', '["S.H., Fakultas Hukum Universitas Dirgantara Marsekal Suryadarma"]', '["Advokat berlisensi, terakreditasi Perhimpunan Advokat Indonesia (PERADI)"]', '["Indonesia","Inggris","Jepang (JFT A2)"]', '["Riset Hukum","Penyusunan Dokumen Hukum","Pidana","Kontrak"]', '{"id":"media-basit-rezki","filename":"basit-rezki.webp","sourceFilename":"Basit.png","mimeType":"image/webp","size":67468,"width":800,"height":1000,"aspectRatio":"4:5","url":"/team/basit-rezki.webp","sizes":{"sm":"/team/basit-rezki-400w.webp","md":"/team/basit-rezki-600w.webp","lg":"/team/basit-rezki-800w.webp"},"srcSet":"/team/basit-rezki-400w.webp 400w, /team/basit-rezki-600w.webp 600w, /team/basit-rezki-800w.webp 800w","alt":"Foto Basit Rezki, S.H."}', 2, 1) ON DUPLICATE KEY UPDATE `display_name` = VALUES(`display_name`), `role_title` = VALUES(`role_title`);
INSERT INTO `team_members` (`id`, `slug`, `full_name`, `honorific`, `display_name`, `role_title`, `group_name`, `motto`, `short_bio`, `full_bio`, `education_json`, `credentials_json`, `languages_json`, `tags_json`, `photo_json`, `display_order`, `is_published`) VALUES ('team-3', 'haddy-siswanto', 'Haddy Siswanto', 'S.H., CLCP', 'Haddy Siswanto, S.H., CLCP', 'Associate', 'Associate', NULL, 'Associate dan advokat bersertifikasi CLCP, berpengalaman dalam hukum perdata, sengketa pertanahan, perjanjian, hak kekayaan intelektual, serta kepatuhan hukum.', 'Haddy Siswanto merupakan lulusan Fakultas Hukum Universitas Airlangga dengan konsentrasi Hukum Peradilan. Ia merupakan seorang advokat yang memiliki pengalaman dalam penanganan berbagai permasalahan hukum, khususnya di bidang hukum perdata, pertanahan, perjanjian, dan hak kekayaan intelektual. Ia memiliki kompetensi dalam analisis hukum, penyusunan dokumen hukum, pendampingan klien, serta penyelesaian sengketa melalui jalur litigasi maupun nonlitigasi.\n\nDalam perjalanan profesionalnya, Haddy memiliki pengalaman menangani berbagai permasalahan hukum terkait jual beli tanah, sengketa pertanahan, dan perjanjian antarpihak. Pengalamannya mencakup analisis dan investigasi permasalahan hukum, penyusunan somasi dan draf gugatan, klarifikasi kepada instansi terkait, serta pendampingan dan perwakilan klien dalam proses penyelesaian sengketa.\n\nSelain itu, Haddy juga berpengalaman dalam penanganan perkara hak kekayaan intelektual, khususnya sengketa hak cipta dan perkara perdata umum. Ia terlibat dalam penyusunan dan peninjauan dokumen gugatan, analisis permasalahan hukum, pemberian konsultasi hukum, serta perumusan alternatif penyelesaian yang sesuai dengan kebutuhan klien.\n\nHaddy juga memiliki sertifikasi Certified Legal Compliance Professional (CLCP) yang memperkuat kompetensinya dalam bidang kepatuhan hukum (legal compliance), meliputi kepatuhan di bidang bisnis, perizinan usaha, perpajakan, ketenagakerjaan, pengadaan barang dan jasa, serta penyusunan standar operasional prosedur berbasis kepatuhan hukum.\n\nSebagai Associate di Ferdinan Silalahi dan Rekan Law Firm, Haddy mengandalkan pengalaman dan pemahaman hukumnya untuk mendukung penanganan berbagai kebutuhan hukum klien. Dengan kemampuan analitis, komunikasi, dan penyelesaian masalah, ia berkomitmen untuk memberikan pendampingan serta solusi hukum yang profesional, efektif, dan berorientasi pada kepentingan klien.', '["S.H., Fakultas Hukum Universitas Airlangga (Konsentrasi Hukum Peradilan)"]', '["Advokat","Certified Legal Compliance Professional (CLCP)"]', '[]', '["Hukum Perdata","Pertanahan","Perjanjian","Hak Kekayaan Intelektual","Legal Compliance"]', '{"id":"media-haddy-siswanto","filename":"haddy-siswanto.webp","sourceFilename":"Haddy.png","mimeType":"image/webp","size":37442,"width":800,"height":1000,"aspectRatio":"4:5","url":"/team/haddy-siswanto.webp","sizes":{"sm":"/team/haddy-siswanto-400w.webp","md":"/team/haddy-siswanto-600w.webp","lg":"/team/haddy-siswanto-800w.webp"},"srcSet":"/team/haddy-siswanto-400w.webp 400w, /team/haddy-siswanto-600w.webp 600w, /team/haddy-siswanto-800w.webp 800w","alt":"Foto Haddy Siswanto, S.H., CLCP"}', 3, 1) ON DUPLICATE KEY UPDATE `display_name` = VALUES(`display_name`), `role_title` = VALUES(`role_title`);
INSERT INTO `team_members` (`id`, `slug`, `full_name`, `honorific`, `display_name`, `role_title`, `group_name`, `motto`, `short_bio`, `full_bio`, `education_json`, `credentials_json`, `languages_json`, `tags_json`, `photo_json`, `display_order`, `is_published`) VALUES ('team-4', 'benny', 'Benny', 'S.H., M.H.', 'Benny, S.H., M.H.', 'Associate', 'Associate', NULL, 'Associate lulusan Magister Hukum Bisnis UPH dengan pengalaman di bidang hukum litigasi, manajemen perkara, konsultasi hukum, dan penyelesaian sengketa.', 'Benny merupakan lulusan Sarjana Hukum dari Universitas Kristen Indonesia dan Magister Hukum Bisnis dari Universitas Pelita Harapan. Ia memiliki pengalaman profesional di bidang hukum litigasi, khususnya dalam pengelolaan perkara, konsultasi hukum, manajemen litigasi, serta penyelesaian sengketa. Latar belakang pendidikannya di bidang hukum bisnis turut memperkuat pemahamannya terhadap aspek hukum dan kebutuhan dunia usaha.\n\nDalam perjalanan profesionalnya, Benny memiliki pengalaman menangani dan mengelola berbagai proses litigasi, termasuk melakukan konsultasi hukum, memberikan pendampingan dan nasihat hukum, serta mengoordinasikan penanganan perkara dengan advokat eksternal. Ia juga berpengalaman dalam pengelolaan administrasi perkara, penyusunan laporan, dan dokumentasi hukum untuk memastikan setiap proses penanganan perkara berjalan secara terstruktur.\n\nSelain itu, Benny memiliki pengalaman dalam manajemen tim litigasi dan pengawasan penanganan perkara, termasuk mengoordinasikan strategi.', '["Sarjana Hukum, Universitas Kristen Indonesia","Magister Hukum Bisnis, Universitas Pelita Harapan"]', '[]', '[]', '["Hukum Litigasi","Manajemen Litigasi","Penyelesaian Sengketa","Hukum Bisnis"]', '{"id":"media-benny","filename":"benny.webp","sourceFilename":"Benny.png","mimeType":"image/webp","size":50486,"width":800,"height":1000,"aspectRatio":"4:5","url":"/team/benny.webp","sizes":{"sm":"/team/benny-400w.webp","md":"/team/benny-600w.webp","lg":"/team/benny-800w.webp"},"srcSet":"/team/benny-400w.webp 400w, /team/benny-600w.webp 600w, /team/benny-800w.webp 800w","alt":"Foto Benny, S.H., M.H."}', 4, 1) ON DUPLICATE KEY UPDATE `display_name` = VALUES(`display_name`), `role_title` = VALUES(`role_title`);
INSERT INTO `team_members` (`id`, `slug`, `full_name`, `honorific`, `display_name`, `role_title`, `group_name`, `motto`, `short_bio`, `full_bio`, `education_json`, `credentials_json`, `languages_json`, `tags_json`, `photo_json`, `display_order`, `is_published`) VALUES ('team-5', 'delia-zaizafun', 'Delia Zaizafun', 'S.H., M.H.', 'Delia Zaizafun, S.H., M.H.', 'Legal Administrator', 'Legal Administrator', NULL, 'Legal Administrator, lulusan Magister Hukum UGM (*cumlaude*) dan penerima Beasiswa LPDP, berpengalaman dalam sengketa pajak dan kepabeanan serta administrasi perkara.', 'Delia Zaizafun merupakan lulusan Magister Hukum Universitas Gadjah Mada dengan predikat *cumlaude* dan penerima Beasiswa LPDP RI. Ia memiliki latar belakang akademik di bidang hukum pidana serta pengalaman profesional dalam penanganan perkara litigasi, administrasi hukum, dan pengelolaan dokumen perkara.\n\nDalam pengalaman profesional sebelumnya sebagai Staf Litigasi, Delia terlibat langsung dalam penanganan 10 sengketa pajak dan kepabeanan, mulai dari pendaftaran gugatan, proses banding, peninjauan kembali, hingga persidangan dan upaya hukum lanjutan. Ia juga berpengalaman menyusun dan meninjau lebih dari 100 dokumen hukum dan dokumen persidangan, melakukan riset serta analisis terhadap lebih dari 50 peraturan perpajakan dan putusan pengadilan, serta menyusun *legal opinion* dan memorandum hukum untuk mendukung analisis dan penyelesaian sengketa.\n\nSelain itu, Delia memiliki pengalaman dalam koordinasi administrasi perkara, pengelolaan basis data kasus, dan pengarsipan dokumen hukum secara sistematis. Pengalamannya di bidang administrasi kepaniteraan di Mahkamah Syar\'iyah Kota Banda Aceh turut memperkuat kemampuannya dalam pengelolaan surat masuk dan keluar, pembaruan register perkara, serta penataan arsip perkara.\n\nDi Ferdinan Silalahi dan Rekan Law Firm, Delia menjalankan peran sebagai Legal Administrator dengan mengandalkan ketelitian, kemampuan analitis, dan keterampilan pengelolaan dokumen untuk mendukung kelancaran administrasi hukum serta operasional firma. Ia berkomitmen untuk memberikan dukungan profesional yang terstruktur dan efisien demi menunjang kualitas pelayanan hukum kepada klien.', '["Magister Hukum, Universitas Gadjah Mada (Cumlaude); penerima Beasiswa LPDP RI"]', '[]', '[]', '["Litigasi Pajak dan Kepabeanan","Hukum Pidana","Administrasi Perkara","Legal Opinion"]', '{"id":"media-delia-zaizafun","filename":"delia-zaizafun.webp","sourceFilename":"Delia.png","mimeType":"image/webp","size":50016,"width":800,"height":1000,"aspectRatio":"4:5","url":"/team/delia-zaizafun.webp","sizes":{"sm":"/team/delia-zaizafun-400w.webp","md":"/team/delia-zaizafun-600w.webp","lg":"/team/delia-zaizafun-800w.webp"},"srcSet":"/team/delia-zaizafun-400w.webp 400w, /team/delia-zaizafun-600w.webp 600w, /team/delia-zaizafun-800w.webp 800w","alt":"Foto Delia Zaizafun, S.H., M.H."}', 5, 1) ON DUPLICATE KEY UPDATE `display_name` = VALUES(`display_name`), `role_title` = VALUES(`role_title`);
INSERT INTO `team_members` (`id`, `slug`, `full_name`, `honorific`, `display_name`, `role_title`, `group_name`, `motto`, `short_bio`, `full_bio`, `education_json`, `credentials_json`, `languages_json`, `tags_json`, `photo_json`, `display_order`, `is_published`) VALUES ('team-6', 'farhah-tri-febriani', 'Farhah Tri Febriani', 'S.H.', 'Farhah Tri Febriani, S.H.', 'Legal Administrator', 'Legal Administrator', NULL, 'Legal Administrator lulusan UIN Syarif Hidayatullah Jakarta, berpengalaman dalam *legal drafting*, riset hukum, serta pengelolaan dan pengarsipan dokumen hukum.', 'Farhah Tri Febriani, S.H. merupakan lulusan Sarjana Hukum dari Universitas Islam Negeri Syarif Hidayatullah Jakarta, tempat beliau mengembangkan pemahaman yang kokoh dan komprehensif mengenai hukum Indonesia maupun prinsip-prinsip hukum Islam.\n\nSelama masa studinya, Farhah secara aktif memperoleh pengalaman langsung dalam praktik hukum dan administrasi, meliputi penyusunan *legal opinion*, pengelolaan dan pengarsipan dokumen hukum, serta koordinasi yang efektif dengan berbagai pihak di beragam lingkungan institusional. Pengalaman-pengalaman tersebut telah mengasah kemampuannya untuk bekerja dengan akurasi, efisiensi, dan tingkat profesionalisme yang tinggi dalam lingkungan hukum yang dinamis.\n\nDengan keahlian yang komprehensif dalam *legal drafting*, *legal research*, administrasi, dan komunikasi profesional, Farhah berkomitmen untuk mendukung kebutuhan operasional dan hukum kantor dengan integritas dan ketelitian, memastikan setiap tugas ditangani dengan perhatian dan kehati-hatian yang optimal.', '["S.H., Universitas Islam Negeri Syarif Hidayatullah Jakarta"]', '[]', '[]', '["Legal Drafting","Legal Research","Administrasi Hukum","Legal Opinion"]', '{"id":"media-farhah-tri-febriani","filename":"farhah-tri-febriani.webp","sourceFilename":"Farhah.png","mimeType":"image/webp","size":65178,"width":800,"height":1000,"aspectRatio":"4:5","url":"/team/farhah-tri-febriani.webp","sizes":{"sm":"/team/farhah-tri-febriani-400w.webp","md":"/team/farhah-tri-febriani-600w.webp","lg":"/team/farhah-tri-febriani-800w.webp"},"srcSet":"/team/farhah-tri-febriani-400w.webp 400w, /team/farhah-tri-febriani-600w.webp 600w, /team/farhah-tri-febriani-800w.webp 800w","alt":"Foto Farhah Tri Febriani, S.H."}', 6, 1) ON DUPLICATE KEY UPDATE `display_name` = VALUES(`display_name`), `role_title` = VALUES(`role_title`);
INSERT INTO `team_members` (`id`, `slug`, `full_name`, `honorific`, `display_name`, `role_title`, `group_name`, `motto`, `short_bio`, `full_bio`, `education_json`, `credentials_json`, `languages_json`, `tags_json`, `photo_json`, `display_order`, `is_published`) VALUES ('team-7', 'kahlil-mawardi-savana', 'Kahlil Mawardi Savana', 'S.H.', 'Kahlil Mawardi Savana, S.H.', 'Legal Administrator', 'Legal Administrator', NULL, 'Legal Administrator dengan pengalaman di bidang hukum korporasi, ketenagakerjaan, hubungan industrial, serta penyusunan dan administrasi dokumen hukum.', 'Kahlil Mawardi Savana merupakan lulusan Sarjana Hukum Universitas Jenderal Soedirman dengan konsentrasi Hukum Internasional. Ia memiliki pengalaman profesional di bidang hukum korporasi, ketenagakerjaan, hubungan industrial, serta administrasi dan dokumentasi hukum. Dengan pemahaman mengenai regulasi ketenagakerjaan dan kepatuhan hukum perusahaan, ia memiliki kompetensi dalam penyusunan dokumen hukum, pengelolaan administrasi perkara, serta koordinasi dengan klien dan instansi terkait.\n\nDalam pengalaman profesionalnya, Kahlil terlibat dalam pengelolaan berbagai kebutuhan administrasi dan dokumentasi hukum perusahaan, termasuk penyusunan dan peninjauan perjanjian kerja waktu tertentu (PKWT) dan perjanjian kerja waktu tidak tertentu (PKWTT), peraturan perusahaan, risalah rapat, surat kuasa, serta dokumen hukum korporasi lainnya. Ia juga berpengalaman dalam meninjau lebih dari 60 perjanjian komersial, termasuk kontrak vendor, perjanjian jasa, dan perjanjian kerja sama dalam bahasa Indonesia maupun Inggris.\n\nSelain itu, Kahlil memiliki pengalaman dalam mendukung penanganan perselisihan hubungan industrial melalui persiapan dokumen mediasi bipartit dan tripartit, penyusunan somasi, serta koordinasi penyelesaian permasalahan hukum sebelum memasuki proses litigasi. Pengalamannya juga mencakup pengelolaan arsip lebih dari 30 berkas transaksi dan administrasi perkara, pengurusan perizinan usaha melalui sistem OSS RBA dan AHU Online, serta pendampingan administrasi penerbitan Nomor Induk Berusaha (NIB) bagi pelaku UMKM.\n\nSebagai Legal Administrator di Ferdinan Silalahi dan Rekan Law Firm, Kahlil berperan dalam mendukung pengelolaan administrasi hukum, dokumentasi perkara, penyusunan dan pengarsipan dokumen, serta koordinasi kebutuhan administratif firma. Dengan ketelitian, kemampuan analitis, dan pemahaman di bidang hukum korporasi serta ketenagakerjaan, ia berkomitmen untuk menunjang kelancaran operasional firma secara sistematis dan profesional.', '["S.H., Fakultas Hukum Universitas Jenderal Soedirman (Konsentrasi Hukum Internasional)"]', '[]', '["Indonesia","Inggris"]', '["Hukum Korporasi","Ketenagakerjaan","Hubungan Industrial","Administrasi Hukum"]', '{"id":"media-kahlil-mawardi-savana","filename":"kahlil-mawardi-savana.webp","sourceFilename":"Kahlil.png","mimeType":"image/webp","size":39990,"width":800,"height":1000,"aspectRatio":"4:5","url":"/team/kahlil-mawardi-savana.webp","sizes":{"sm":"/team/kahlil-mawardi-savana-400w.webp","md":"/team/kahlil-mawardi-savana-600w.webp","lg":"/team/kahlil-mawardi-savana-800w.webp"},"srcSet":"/team/kahlil-mawardi-savana-400w.webp 400w, /team/kahlil-mawardi-savana-600w.webp 600w, /team/kahlil-mawardi-savana-800w.webp 800w","alt":"Foto Kahlil Mawardi Savana, S.H."}', 7, 1) ON DUPLICATE KEY UPDATE `display_name` = VALUES(`display_name`), `role_title` = VALUES(`role_title`);

-- 6. Case Records (Rekam Jejak Perkara)
