na khusus di pengadilan","alt":"Pendampingan sidang advokasi perkara pidana"},{"url":"/images/cases/tindak-pidana-penggelapan/tindak-pidana-penggelapan-8.webp","caption":"Penyusunan risalah dan pengawalan proses hukum hingga penetapan akhir","alt":"Pengawalan putusan dan penetapan akhir perkara pidana"}]') ON DUPLICATE KEY UPDATE `case_type` = VALUES(`case_type`), `region` = VALUES(`region`);
